insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_communication','communication','noun','the process of sharing information, ideas or feelings with other people','[{"senseId":"communication_1","meaning":"the process of sharing information, ideas or feelings with other people","acceptedParaphrases":["sharing information","exchanging ideas and messages"],"masteryContexts":[{"contextId":"u9_01_communication_meaning","text":"Employers often say that communication is the most important skill a new worker can have.","meaning":"the ability to share ideas clearly with others","wrongMeanings":["the ability to work long hours without a break","the ability to repair computers quickly","the ability to follow rules carefully"]},{"contextId":"u9_01_communication_paraphrase","text":"During the flood, all communication with the town was cut off because the phone lines were damaged.","meaning":"contact and the exchange of messages","wrongMeanings":["the supply of electricity and clean water","the movement of cars along the roads","the delivery of food to the shops"]}],"situationDistractors":["A student sat alone in the library and read silently for an hour.","A boy fixed the chain on his bicycle without asking anyone for help.","A girl stored her old photos on a memory stick and put it in a drawer.","A man locked his diary in a drawer so nobody could read it.","A girl went for a long run on her own before breakfast.","A boy tidied his bedroom while his family were out."],"gapDistractors":[{"contextId":"u9_01_communication_gap_1","answer":"communication","wrong":["frustration","conclusion","generation"]},{"contextId":"u9_01_communication_gap_2","answer":"communication","wrong":["perception","introduction","workforce"]},{"contextId":"u9_01_communication_gap_3","answer":"communication","wrong":["accuracy","frustration","conference"]}],"spellingErrors":["comunication","communicasion","commnication","communcation","communicaton","comunicattion"],"wordFamilyForms":[{"form":"communication","partOfSpeech":"noun","example":"Good communication between parents and teachers helps students succeed.","pedagogicallyUseful":true},{"form":"communicate","partOfSpeech":"verb","example":"Teenagers often communicate with friends through short voice messages.","pedagogicallyUseful":true,"altExample":"Dolphins communicate with each other using clicks and whistles."},{"form":"communicative","partOfSpeech":"adjective","example":"The new teacher uses a communicative approach, so students speak a lot in class.","pedagogicallyUseful":true,"altExample":"The test checks how communicative students are in real conversations."}],"masteryPassages":[{"passageId":"u9_01_communication_passage_1","contextId":"u9_01_communication_gap_1","text":"The project failed because nobody knew who was doing what. Better ____ between the team members would have solved the problem.","answer":"communication"},{"passageId":"u9_01_communication_passage_2","contextId":"u9_01_communication_gap_2","text":"Emojis have become an important part of online ____. They show feelings that are hard to express in a few typed words.","answer":"communication"}],"contextDependentParaphrases":[],"wrongParaphrases":["storing information","repairing machines","working alone"],"misleadingDistractors":["the process of storing information safely","the habit of working alone without help","the skill of repairing electronic devices"],"teacherNote":"Noun: the sharing of information, ideas or feelings (good communication, communication skills, lines of communication). Uncountable in this sense. The verb communicate, the adjective communicative and the noun communicator are taught in the Word Family pathway."}]'::jsonb,'["communicate","communicative"]'::jsonb,'["communication skills","clear communication","a form of communication"]'::jsonb,'live'),
('vocab_signalling','signalling','verb','giving a message or warning by making a movement, sound or light','[{"senseId":"signalling_1","meaning":"giving a message or warning by making a movement, sound or light","acceptedParaphrases":["giving a sign","showing a message with a movement or light"],"masteryContexts":[{"contextId":"u9_02_signalling_meaning","text":"The lifeguard was signalling to the swimmers to come back towards the beach.","meaning":"making a movement to give a message","wrongMeanings":["making a loud complaint to someone","staying silent so nobody notices","writing a message on paper"]},{"contextId":"u9_02_signalling_paraphrase","text":"A flashing red light on the dashboard was signalling that the car needed petrol.","meaning":"showing a warning with a light","wrongMeanings":["hiding a problem from the driver","recording a journey for later","playing music to the passengers"]}],"situationDistractors":["A driver sat quietly in a traffic jam, listening to the radio.","A girl wrote a long letter to her grandmother in Canada.","A student kept his answer secret and said nothing to the class.","A man stood completely still at the bus stop with his hands in his pockets.","A girl typed a long essay on her laptop.","A boy kept his eyes closed and listened to music."],"gapDistractors":[{"contextId":"u9_02_signalling_gap_1","answer":"signalling","wrong":["surviving","banning","evaluating"]},{"contextId":"u9_02_signalling_gap_2","answer":"signalling","wrong":["research","surviving","differentiating"]},{"contextId":"u9_02_signalling_gap_3","answer":"signalling","wrong":["surviving","researching","banning"]}],"spellingErrors":["signalinng","signalliing","signeling","singalling","signallling","sigalling"],"masteryPassages":[{"passageId":"u9_02_signalling_passage_1","contextId":"u9_02_signalling_gap_1","text":"The lorry driver could not see behind him. A worker stood at the back, ____ with both arms to show him when to stop.","answer":"signalling"},{"passageId":"u9_02_signalling_passage_2","contextId":"u9_02_signalling_gap_2","text":"The red light on the router kept flashing. It was ____ that the internet connection had been lost.","answer":"signalling"}],"contextDependentParaphrases":[],"wrongParaphrases":["hiding a message","writing a report","asking a question"],"misleadingDistractors":["hiding a message so nobody can see it","writing a long and detailed report","refusing to answer a question"],"teacherNote":"Verb (-ing form, British spelling with double l): giving a message or warning with a movement, sound or light (signalling to someone, signalling that ..., signalling for help). American English uses a single l. The noun signal and the past form signalled are taught in the Word Family pathway."}]'::jsonb,'[]'::jsonb,'["signalling to someone","signalling for help","signalling that something is wrong"]'::jsonb,'live'),
('vocab_represent','represent','verb','to be a sign or symbol of something, or to speak or act for another person or group','[{"senseId":"represent_1","meaning":"to be a sign or symbol of something, or to speak or act for another person or group","acceptedParaphrases":["stand for","be a symbol of"],"masteryContexts":[{"contextId":"u9_03_represent_meaning","text":"In many emoji sets, a red heart is used to represent love or strong support.","meaning":"to be a sign or symbol of something","wrongMeanings":["to cause a feeling or emotion","to hide a meaning from others","to replace an older symbol"]},{"contextId":"u9_03_represent_paraphrase","text":"Mei was proud to represent her school at the national debating competition.","meaning":"to speak or act for a group","wrongMeanings":["to compete against a group","to leave a group permanently","to train a group of beginners"]}],"situationDistractors":["A boy painted his bedroom wall a brighter colour.","A girl hid her diary under her bed so her brother could not read it.","A teacher made the font on her slides larger so everyone could read it.","A student threw away an old poster that had torn.","A boy cleaned the whiteboard at the end of the lesson.","A girl bought a new pencil case for school."],"gapDistractors":[{"contextId":"u9_03_represent_gap_1","answer":"represent","wrong":["survive","evaluate","differentiate"]},{"contextId":"u9_03_represent_gap_2","answer":"represent","wrong":["survive","suggest","research"]},{"contextId":"u9_03_represent_gap_3","answer":"represent","wrong":["survive","research","suggest"]}],"spellingErrors":["reprisent","represant","repressent","reprezent","representt","reprasent"],"wordFamilyForms":[{"form":"represent","partOfSpeech":"verb","example":"On this map, blue lines represent rivers.","pedagogicallyUseful":true},{"form":"representative","partOfSpeech":"noun","example":"Each class elects a representative for the student council.","pedagogicallyUseful":true,"altExample":"A company representative answered our questions at the fair."},{"form":"representation","partOfSpeech":"noun","example":"The painting is a representation of life in a busy port.","pedagogicallyUseful":true,"altExample":"The flag is a representation of the country’s history."}],"masteryPassages":[{"passageId":"u9_03_represent_passage_1","contextId":"u9_03_represent_gap_1","text":"Look at the graph carefully. The orange lines ____ boys and the purple lines show girls.","answer":"represent"},{"passageId":"u9_03_represent_passage_2","contextId":"u9_03_represent_gap_2","text":"Every year, each class votes for two students. These students ____ their classmates at the school council.","answer":"represent"}],"contextDependentParaphrases":[],"wrongParaphrases":["decorate","repair","replace"],"misleadingDistractors":["to make something look more attractive","to keep something secret from others","to change something so it is easier to use"],"teacherNote":"Verb: (1) to be a sign or symbol of something (the colours represent ...); (2) to speak or act officially for a person or group (represent the school). Both senses are common in Paper 1 texts. The nouns representation and representative and the adjective representative are taught in the Word Family pathway."}]'::jsonb,'["representative","representation"]'::jsonb,'["represent the school","represent an idea","be chosen to represent a group"]'::jsonb,'live'),
('vocab_effective_9','effective','adjective','working well and producing the result that was wanted','[{"senseId":"effective_9_1","meaning":"working well and producing the result that was wanted","acceptedParaphrases":["successful","producing the intended result"],"masteryContexts":[{"contextId":"u9_04_effective_9_meaning","text":"Using simple pictures was an effective way to explain the rules to the younger children.","meaning":"working well to get the result wanted","wrongMeanings":["cheap but slow to produce","popular but hard to understand","new but not yet tested"]},{"contextId":"u9_04_effective_9_paraphrase","text":"The campaign was so effective that the number of students cycling to school doubled.","meaning":"producing the result that was intended","wrongMeanings":["costing more than was planned","lasting longer than was planned","attracting more criticism than expected"]}],"situationDistractors":["A speaker talked for an hour, but nobody understood his main point.","A poster used tiny writing, so people walked past without reading it.","A boy sent his friend ten messages, but none of them answered her question.","A shop spent a lot on adverts, but its sales did not change.","A student revised for hours but used the wrong notes and failed.","A new rule about queuing was ignored by everyone."],"gapDistractors":[{"contextId":"u9_04_effective_9_gap_1","answer":"effective","wrong":["banned","portable","passive"]},{"contextId":"u9_04_effective_9_gap_2","answer":"effective","wrong":["portable","optional","virtual"]},{"contextId":"u9_04_effective_9_gap_3","answer":"effective","wrong":["portable","tech-savvy","physical"]}],"spellingErrors":["effectve","efective","effektive","effecttive","effectiv","effectave"],"wordFamilyForms":[{"form":"effective","partOfSpeech":"adjective","example":"Short, regular practice is an effective way to remember new words.","pedagogicallyUseful":true},{"form":"effectively","partOfSpeech":"adverb","example":"Good speakers use pauses to communicate effectively.","pedagogicallyUseful":true,"altExample":"The new system deals with complaints more effectively."},{"form":"ineffective","partOfSpeech":"adjective","example":"The warning was ineffective because nobody read it.","pedagogicallyUseful":true,"altExample":"Shouting at the dog was completely ineffective."}],"masteryPassages":[{"passageId":"u9_04_effective_9_passage_1","contextId":"u9_04_effective_9_gap_1","text":"Shouting at the class did not make them quieter. The teacher found that waiting silently was far more ____.","answer":"effective"},{"passageId":"u9_04_effective_9_passage_2","contextId":"u9_04_effective_9_gap_2","text":"The anti-litter posters were so ____ that the playground was clean within a week. The head teacher plans to use them again.","answer":"effective"}],"contextDependentParaphrases":[],"wrongParaphrases":["expensive","complicated","old-fashioned"],"misleadingDistractors":["costing a lot of money to use","taking a very long time to finish","looking modern and attractive"],"teacherNote":"Adjective: working well and producing the result that is wanted (an effective way to ..., effective communication). Unit 9 uses it for messages, presentations and ways of communicating; Unit 6 taught it for study methods. Boundary: effective is about results; efficient is about not wasting time or energy. The adverb effectively and the noun effectiveness are taught in the Word Family pathway."}]'::jsonb,'["effectively","ineffective"]'::jsonb,'["an effective way to","highly effective","effective communication"]'::jsonb,'live'),
('vocab_portable','portable','adjective','light and small enough to be carried or moved easily','[{"senseId":"portable_1","meaning":"light and small enough to be carried or moved easily","acceptedParaphrases":["easy to carry","light enough to move around"],"masteryContexts":[{"contextId":"u9_05_portable_meaning","text":"The first portable phones were as heavy as a brick, but today they fit in a pocket.","meaning":"able to be carried around easily","wrongMeanings":["very expensive to buy","attached to one place","easy to break"]},{"contextId":"u9_05_portable_paraphrase","text":"The school bought a portable whiteboard so teachers can use it in any classroom.","meaning":"light enough to be moved from place to place","wrongMeanings":["too large to fit through a door","only usable by one teacher","designed to stay on one wall"]}],"situationDistractors":["Workers fixed a huge television to the wall with strong metal screws.","A family bought a piano so heavy that four people were needed to move it.","The library installed a large printer that stays in one corner of the room.","A builder poured concrete to make a new garage floor.","A family installed a heavy washing machine in the kitchen.","Engineers built a radio tower on top of a hill."],"gapDistractors":[{"contextId":"u9_05_portable_gap_1","answer":"portable","wrong":["constructive","banned","non-verbal"]},{"contextId":"u9_05_portable_gap_2","answer":"portable","wrong":["casual","tech-savvy","informal"]},{"contextId":"u9_05_portable_gap_3","answer":"portable","wrong":["tech-savvy","constructive","relevant"]}],"spellingErrors":["portible","portabel","porteble","portabble","portabal","portabl"],"masteryPassages":[{"passageId":"u9_05_portable_passage_1","contextId":"u9_05_portable_gap_1","text":"Our grandparents had one huge telephone fixed to the wall in the hall. Today, phones are so ____ that we carry them everywhere.","answer":"portable"},{"passageId":"u9_05_portable_passage_2","contextId":"u9_05_portable_gap_2","text":"The band needed a speaker they could carry to the beach. They bought a small ____ one that runs on batteries.","answer":"portable"}],"contextDependentParaphrases":[],"wrongParaphrases":["heavy to lift","fixed in place","easy to break"],"misleadingDistractors":["too heavy to be lifted by one person","fixed firmly to a wall or floor","expensive and difficult to repair"],"teacherNote":"Adjective: light and small enough to be carried or moved easily (a portable charger, a portable speaker). Boundary: portable describes size and weight; mobile describes something that moves or works while moving. The noun portability is taught in the Word Family pathway; \"portably\" is not taught."}]'::jsonb,'[]'::jsonb,'["a portable charger","a portable speaker","small and portable"]'::jsonb,'live'),
('vocab_demonstrate_9','demonstrate','verb','to show clearly how something works or how to do something, or to show that something is true','[{"senseId":"demonstrate_9_1","meaning":"to show clearly how something works or how to do something, or to show that something is true","acceptedParaphrases":["show how to do","prove clearly"],"masteryContexts":[{"contextId":"u9_06_demonstrate_9_meaning","text":"At the start of the workshop, the trainer will demonstrate how to set up a video call.","meaning":"to show how to do something by doing it","wrongMeanings":["to explain something only in writing","to ask others how to do something","to refuse to show how something works"]},{"contextId":"u9_06_demonstrate_9_paraphrase","text":"These experiments demonstrate that people remember pictures better than words.","meaning":"to show clearly that something is true","wrongMeanings":["to suggest that something might be false","to guess something without evidence","to hide that something is true"]}],"situationDistractors":["A boy read the instructions alone and said nothing to anyone.","A girl refused to tell her friends how she had solved the puzzle.","A student asked the teacher to repeat the homework question.","A boy kept his science experiment hidden in a box.","A girl handed in her homework without saying anything.","A student guessed the answer without any evidence."],"gapDistractors":[{"contextId":"u9_06_demonstrate_9_gap_1","answer":"demonstrate","wrong":["ban","survive","launch"]},{"contextId":"u9_06_demonstrate_9_gap_2","answer":"demonstrate","wrong":["survive","ban","differentiate"]},{"contextId":"u9_06_demonstrate_9_gap_3","answer":"demonstrate","wrong":["survive","ban","differentiate"]}],"spellingErrors":["demonstrait","demostrate","demonstrat","demonstate","demmonstrate","demonstreit"],"wordFamilyForms":[{"form":"demonstrate","partOfSpeech":"verb","example":"The chef will demonstrate how to make fresh pasta.","pedagogicallyUseful":true},{"form":"demonstration","partOfSpeech":"noun","example":"The science teacher gave a demonstration of how sound travels.","pedagogicallyUseful":true,"altExample":"The salesman gave us a quick demonstration of the vacuum cleaner."},{"form":"demonstrator","partOfSpeech":"noun","example":"A demonstrator held a sign asking for cleaner air.","pedagogicallyUseful":true,"altExample":"Police spoke calmly to every demonstrator outside the town hall."}],"masteryPassages":[{"passageId":"u9_06_demonstrate_9_passage_1","contextId":"u9_06_demonstrate_9_gap_1","text":"The new students did not know how to use the library computers. A librarian offered to ____ how to search for books.","answer":"demonstrate"},{"passageId":"u9_06_demonstrate_9_passage_2","contextId":"u9_06_demonstrate_9_gap_2","text":"Many people think that reading on screens is just as good as reading on paper. However, some studies ____ that we remember less from screens.","answer":"demonstrate"}],"contextDependentParaphrases":[],"wrongParaphrases":["hide how to do","guess wrongly","forget quickly"],"misleadingDistractors":["to explain something only in writing","to hide how something works","to ask someone to repeat something"],"teacherNote":"Verb: (1) to show how something works or is done, usually by doing it (demonstrate how to ...); (2) to show clearly that something is true (the study demonstrates that ...). Unit 9 uses it for showing skills and presenting evidence; Unit 7 taught showing qualities in an interview. Boundary: \"demonstrate\" in the sense of protesting is not taught here. The nouns demonstration and demonstrator are taught in the Word Family pathway."}]'::jsonb,'["demonstration","demonstrator"]'::jsonb,'["demonstrate how to","demonstrate a skill","clearly demonstrate that"]'::jsonb,'live'),
('vocab_launched_9','launched','verb','started or introduced something new, such as a product, service or campaign, to the public','[{"senseId":"launched_9_1","meaning":"started or introduced something new, such as a product, service or campaign, to the public","acceptedParaphrases":["introduced to the public","started officially"],"masteryContexts":[{"contextId":"u9_07_launched_9_meaning","text":"When the first smartphone was launched, few people imagined how much it would change daily life.","meaning":"introduced to the public for the first time","wrongMeanings":["stopped selling to customers","kept secret from the public","tested only by engineers"]},{"contextId":"u9_07_launched_9_paraphrase","text":"The charity launched an online campaign to help elderly people learn to use video calls.","meaning":"started an organised activity officially","wrongMeanings":["ended an activity early","criticised an activity publicly","paid for an activity secretly"]}],"situationDistractors":["A shop stopped selling an old phone model because nobody wanted it.","A company kept its new product hidden until the designers had finished it.","A technician repaired the school’s broken projector.","A company closed its last shop in the city centre.","A website was shut down after twenty years online.","A team spent another year testing an app in secret."],"gapDistractors":[{"contextId":"u9_07_launched_9_gap_1","answer":"launched","wrong":["survived","differentiated","signalled"]},{"contextId":"u9_07_launched_9_gap_2","answer":"launched","wrong":["survived","evaluated","differentiated"]},{"contextId":"u9_07_launched_9_gap_3","answer":"launched","wrong":["survived","differentiated","represented"]}],"spellingErrors":["lanched","launcht","lawnched","lauched","launchd","launshed"],"masteryPassages":[{"passageId":"u9_07_launched_9_passage_1","contextId":"u9_07_launched_9_gap_1","text":"After two years of testing, the company finally ____ its new translation app last week. Within days, a million people had downloaded it.","answer":"launched"},{"passageId":"u9_07_launched_9_passage_2","contextId":"u9_07_launched_9_gap_2","text":"Worried about cyberbullying, the school ____ a campaign called \"Think before you post\". Posters appeared in every corridor.","answer":"launched"}],"contextDependentParaphrases":[],"wrongParaphrases":["stopped selling","kept secret","repaired"],"misleadingDistractors":["stopped selling something because it was unpopular","kept something secret from customers","repaired something that was broken"],"teacherNote":"Verb (past form, as in the coursebook): started or introduced something new to the public (launched an app, launched a campaign, launched a website). Unit 9 uses it for communication products and campaigns; Unit 8 taught it for business products. Boundary: launching a rocket or a ship is a related literal sense, not taught here. The noun launch and the base form launch are taught in the Word Family pathway."}]'::jsonb,'[]'::jsonb,'["launched a campaign","launched a new app","was officially launched"]'::jsonb,'live'),
('vocab_passive_9','passive','adjective','accepting or receiving things without taking an active part or responding','[{"senseId":"passive_9_1","meaning":"accepting or receiving things without taking an active part or responding","acceptedParaphrases":["not actively involved","just watching or receiving"],"masteryContexts":[{"contextId":"u9_08_passive_9_meaning","text":"Television made audiences passive, but social media lets them comment and share.","meaning":"only receiving, without taking part","wrongMeanings":["angry and critical","well informed and curious","loud and excited"]},{"contextId":"u9_08_passive_9_paraphrase","text":"Instead of being passive listeners, the students were asked to discuss the talk in groups.","meaning":"not actively involved","wrongMeanings":["eager to argue","very well prepared","in charge of the event"]}],"situationDistractors":["A student put up her hand and asked the speaker three questions.","A boy organised the whole class trip and phoned the museum himself.","A girl argued strongly in the debate and changed the audience’s minds.","A student led the group discussion and asked everyone for ideas.","A boy volunteered to present first in front of the class.","A girl wrote to the council to complain about the park."],"gapDistractors":[{"contextId":"u9_08_passive_9_gap_1","answer":"passive","wrong":["portable","face-to-face","banned"]},{"contextId":"u9_08_passive_9_gap_2","answer":"passive","wrong":["portable","relevant","optional"]},{"contextId":"u9_08_passive_9_gap_3","answer":"passive","wrong":["portable","tech-savvy","banned"]}],"spellingErrors":["pasive","passiv","passsive","passeve","pessive","pasiv"],"wordFamilyForms":[{"form":"passive","partOfSpeech":"adjective","example":"Watching television is a passive activity for most children.","pedagogicallyUseful":true},{"form":"passively","partOfSpeech":"adverb","example":"Too many students sit passively and wait for the answers.","pedagogicallyUseful":true,"altExample":"He listened passively and never asked a single question."},{"form":"passivity","partOfSpeech":"noun","example":"The teacher was worried about the passivity of the group during discussions.","pedagogicallyUseful":true,"altExample":"Long lectures can lead to passivity among students."}],"masteryPassages":[{"passageId":"u9_08_passive_9_passage_1","contextId":"u9_08_passive_9_gap_1","text":"In traditional lessons, students sat and listened for an hour. Teachers now want them to stop being ____ listeners and to discuss ideas.","answer":"passive"},{"passageId":"u9_08_passive_9_passage_2","contextId":"u9_08_passive_9_gap_2","text":"Scrolling through videos for hours is a very ____ activity. You simply watch and never create anything yourself.","answer":"passive"}],"contextDependentParaphrases":[],"wrongParaphrases":["in control","very energetic","quick to argue"],"misleadingDistractors":["taking control and making decisions","speaking loudly and with confidence","working quickly and carefully"],"teacherNote":"Adjective: accepting or receiving without taking an active part (passive viewers, a passive audience, passive learning). Unit 9 contrasts passive with interactive communication; Unit 6 taught it for study habits. Boundary: the grammar term \"passive voice\" is related but not the target here. The adverb passively and the noun passivity are taught in the Word Family pathway."}]'::jsonb,'["passively","passivity"]'::jsonb,'["passive viewers","a passive audience","passive screen time"]'::jsonb,'live'),
('vocab_interactive_9','interactive','adjective','allowing information to pass in both directions, so that the user or audience can respond and take part','[{"senseId":"interactive_9_1","meaning":"allowing information to pass in both directions, so that the user or audience can respond and take part","acceptedParaphrases":["two-way","involving the user"],"masteryContexts":[{"contextId":"u9_09_interactive_9_meaning","text":"The teacher used an interactive quiz, so every student answered on their phone and saw the results at once.","meaning":"allowing users to respond and take part","wrongMeanings":["shown to a large audience at once","printed on paper for each student","kept private from the teacher"]},{"contextId":"u9_09_interactive_9_paraphrase","text":"Unlike a printed newspaper, the website is interactive: readers can leave comments and vote in polls.","meaning":"allowing information to pass in both directions","wrongMeanings":["written only by professional journalists","updated once a week","free of advertising"]}],"situationDistractors":["An audience sat in silence and watched a film from start to finish.","A girl read a printed leaflet that gave her no way to ask questions.","A radio station played music all night without any phone-ins.","A man read a printed newspaper on the train.","A class watched a documentary without stopping it.","A girl listened to a recorded lecture with no questions allowed."],"gapDistractors":[{"contextId":"u9_09_interactive_9_gap_1","answer":"interactive","wrong":["banned","passive","underlying"]},{"contextId":"u9_09_interactive_9_gap_2","answer":"interactive","wrong":["banned","casual","underlying"]},{"contextId":"u9_09_interactive_9_gap_3","answer":"interactive","wrong":["portable","underlying","banned"]}],"spellingErrors":["intaractive","interactiv","interactave","intreractive","interractive","interective"],"wordFamilyForms":[{"form":"interactive","partOfSpeech":"adjective","example":"The museum has an interactive screen where visitors can design robots.","pedagogicallyUseful":true},{"form":"interact","partOfSpeech":"verb","example":"Shy students often interact more confidently online.","pedagogicallyUseful":true,"altExample":"Visitors can interact with the robots in the science centre."},{"form":"interaction","partOfSpeech":"noun","example":"Video calls cannot fully replace face-to-face interaction.","pedagogicallyUseful":true,"altExample":"There was very little interaction between the two teams."}],"masteryPassages":[{"passageId":"u9_09_interactive_9_passage_1","contextId":"u9_09_interactive_9_gap_1","text":"The old museum only had glass cases and labels. The new science centre is fully ____, so children can press buttons and run experiments.","answer":"interactive"},{"passageId":"u9_09_interactive_9_passage_2","contextId":"u9_09_interactive_9_gap_2","text":"The online lesson was very ____. Students voted in polls, answered quizzes and sent questions to the teacher.","answer":"interactive"}],"contextDependentParaphrases":[],"wrongParaphrases":["one-way","old-fashioned","hard to see"],"misleadingDistractors":["designed only to be watched or listened to","too difficult for beginners to use","working without electricity"],"teacherNote":"Adjective: allowing two-way exchange, so users or an audience can respond and take part (an interactive whiteboard, an interactive lesson, interactive websites). Unit 9 contrasts interactive with passive communication; Unit 2 taught it for digital media. The verb interact and the noun interaction are taught in the Word Family pathway."}]'::jsonb,'["interact","interaction"]'::jsonb,'["an interactive whiteboard","interactive games","highly interactive"]'::jsonb,'live'),
('vocab_tech_savvy','tech-savvy','adjective','knowing a lot about modern technology and able to use it confidently','[{"senseId":"tech_savvy_1","meaning":"knowing a lot about modern technology and able to use it confidently","acceptedParaphrases":["good with technology","confident using computers and devices"],"masteryContexts":[{"contextId":"u9_10_tech_savvy_meaning","text":"The bank designed its app for tech-savvy customers who never want to visit a branch.","meaning":"confident and skilled with modern technology","wrongMeanings":["nervous about using modern technology","living far from the nearest town","interested only in low prices"]},{"contextId":"u9_10_tech_savvy_paraphrase","text":"Grandma has become quite tech-savvy since she started video-calling her grandchildren.","meaning":"able to use modern devices well","wrongMeanings":["worried about using modern devices","unable to see small writing clearly","too busy to use technology"]}],"situationDistractors":["An old man refused to use a mobile phone because he found it confusing.","A girl asked her friend for help every time her laptop showed an error.","A man still writes all his letters by hand and has never sent an email.","A woman asked her son to turn on her new phone for her.","A boy could not work out how to attach a file to an email.","A man wrote his password on a sticky note because he kept forgetting how to log in."],"gapDistractors":[{"contextId":"u9_10_tech_savvy_gap_1","answer":"tech-savvy","wrong":["banned","optional","underlying"]},{"contextId":"u9_10_tech_savvy_gap_2","answer":"tech-savvy","wrong":["banned","underlying","optional"]},{"contextId":"u9_10_tech_savvy_gap_3","answer":"tech-savvy","wrong":["banned","portable","underlying"]}],"spellingErrors":["tech-savy","tech-savvey","teck-savvy","tech-sawy","tech-sevvy","tech-savvie"],"masteryPassages":[{"passageId":"u9_10_tech_savvy_passage_1","contextId":"u9_10_tech_savvy_gap_1","text":"My grandfather used to be afraid of computers. Now he is so ____ that he edits videos and helps his friends set up their phones.","answer":"tech-savvy"},{"passageId":"u9_10_tech_savvy_passage_2","contextId":"u9_10_tech_savvy_gap_2","text":"The company wants staff who are ____ and comfortable learning new software quickly. Experience with social media is an advantage.","answer":"tech-savvy"}],"contextDependentParaphrases":[],"wrongParaphrases":["afraid of technology","bored by computers","careless with devices"],"misleadingDistractors":["afraid of using new machines","working in a factory that makes computers","interested only in old-fashioned things"],"teacherNote":"Adjective (hyphenated, informal): knowing a lot about modern technology and using it confidently (a tech-savvy generation, tech-savvy users). Often used before a noun or after be/become. It has no useful word family (savvy alone is informal and rare at this level), so Word Families is not counted for it."}]'::jsonb,'[]'::jsonb,'["tech-savvy users","a tech-savvy generation","become tech-savvy"]'::jsonb,'live')
