('u9_idea_communication',9,'idea_set','{"originalIdea":"Good communication between the coach and the players helped the team win.","accurateParaphrases":["The team won partly because the coach and the players shared information clearly.","Because the coach and players understood each other well, the team was successful.","Clear contact and exchange of ideas between the coach and the players helped them win."],"meaningInvariants":[{"type":"cause_effect","value":"sharing information clearly helped"}],"distractors":[{"text":"Strong competition between the coach and the players helped the team win.","misconceptionCategory":"meaning_confusion"},{"text":"Poor contact between the coach and the players helped the team win.","misconceptionCategory":"polarity_change"},{"text":"Good contact between the coach and the players will help the team win.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_communication"],"primaryEvidenceTargetId":"vocab_communication"}'::jsonb,'live'),
('u9_idea_signalling',9,'idea_set','{"originalIdea":"The police officer was signalling to the drivers to slow down.","accurateParaphrases":["The police officer was using hand movements to tell the drivers to slow down.","With gestures, the police officer was showing the drivers that they should go more slowly.","The officer was giving the drivers a sign to reduce their speed."],"meaningInvariants":[{"type":"meaning","value":"using movements to give a message"}],"distractors":[{"text":"The police officer was shouting at the drivers to slow down.","misconceptionCategory":"meaning_confusion"},{"text":"The police officer was signalling to the drivers to speed up.","misconceptionCategory":"polarity_change"},{"text":"The drivers were signalling to the police officer to slow down.","misconceptionCategory":"role_reversal"}],"linkedVocabularyIds":["vocab_signalling"],"primaryEvidenceTargetId":"vocab_signalling"}'::jsonb,'live'),
('u9_idea_represent',9,'idea_set','{"originalIdea":"Two students were chosen to represent the school at the national debate.","accurateParaphrases":["Two students were selected to speak for the school at the national debate.","The school picked two students to take part in the national debate on its behalf.","At the national debate, two chosen students acted for the school."],"meaningInvariants":[{"type":"meaning","value":"act or speak for"}],"distractors":[{"text":"Two students were chosen to judge the school at the national debate.","misconceptionCategory":"meaning_confusion"},{"text":"Twenty students were chosen to speak for the school at the national debate.","misconceptionCategory":"quantity_change"},{"text":"Two students will be chosen to speak for the school at the national debate.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_represent"],"primaryEvidenceTargetId":"vocab_represent"}'::jsonb,'live'),
('u9_idea_effective',9,'idea_set','{"originalIdea":"Short daily practice is more effective than one long session each week.","accurateParaphrases":["Practising a little every day works better than one long session a week.","A short session every day gives better results than a single long one weekly.","You get better results from brief practice each day than from one long weekly session."],"meaningInvariants":[{"type":"comparison","value":"daily practice works better"}],"distractors":[{"text":"Short daily practice is less successful than one long session each week.","misconceptionCategory":"comparison_reversal"},{"text":"Short daily practice is more enjoyable than one long session each week.","misconceptionCategory":"meaning_confusion"},{"text":"Short daily practice is as successful as one long session each week.","misconceptionCategory":"degree_change"}],"linkedVocabularyIds":["vocab_effective_9"],"primaryEvidenceTargetId":"vocab_effective_9"}'::jsonb,'live'),
('u9_idea_portable',9,'idea_set','{"originalIdea":"The new speaker is small and portable, so you can take it anywhere.","accurateParaphrases":["The new speaker is little and easy to carry, so it can go everywhere with you.","Because the new speaker is small and light to carry, you can bring it wherever you go.","You can take the new speaker anywhere because it is compact and easy to move."],"meaningInvariants":[{"type":"meaning","value":"easy to carry"}],"distractors":[{"text":"The new speaker is small and powerful, so you can take it anywhere.","misconceptionCategory":"meaning_confusion"},{"text":"The new speaker is large and fixed, so you cannot take it anywhere.","misconceptionCategory":"polarity_change"},{"text":"The old speaker was small and easy to carry, so you could take it anywhere.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_portable"],"primaryEvidenceTargetId":"vocab_portable"}'::jsonb,'live'),
('u9_idea_demonstrate',9,'idea_set','{"originalIdea":"The study demonstrates that students remember more when they take handwritten notes.","accurateParaphrases":["The study shows clearly that students who write notes by hand remember more.","According to the study, taking notes by hand helps students remember more.","The study proves that handwritten notes help students to remember more."],"meaningInvariants":[{"type":"meaning","value":"shows clearly"}],"distractors":[{"text":"The study suggests that students might remember more when they take handwritten notes.","misconceptionCategory":"certainty_change"},{"text":"The study shows that students remember less when they take handwritten notes.","misconceptionCategory":"polarity_change"},{"text":"The study shows that teachers remember more when they take handwritten notes.","misconceptionCategory":"role_change"}],"linkedVocabularyIds":["vocab_demonstrate_9"],"primaryEvidenceTargetId":"vocab_demonstrate_9"}'::jsonb,'live'),
('u9_idea_launched',9,'idea_set','{"originalIdea":"The charity launched an online campaign to help children learn to read.","accurateParaphrases":["The charity started an online campaign to help children learn to read.","An internet campaign to help children read was begun by the charity.","The charity began a campaign on the internet so that more children could learn to read."],"meaningInvariants":[{"type":"meaning","value":"started"}],"distractors":[{"text":"The charity ended an online campaign to help children learn to read.","misconceptionCategory":"polarity_change"},{"text":"The charity criticised an online campaign to help children learn to read.","misconceptionCategory":"meaning_confusion"},{"text":"The charity is planning an online campaign to help children learn to read.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_launched_9"],"primaryEvidenceTargetId":"vocab_launched_9"}'::jsonb,'live'),
('u9_idea_passive',9,'idea_set','{"originalIdea":"Watching videos is a passive activity, while making them is creative.","accurateParaphrases":["Watching videos does not involve taking part, but making them involves creativity.","People who watch videos only receive them, while people who make them create something.","Viewing videos requires no active involvement, unlike making them, which is creative."],"meaningInvariants":[{"type":"contrast","value":"watching involves no active part"}],"distractors":[{"text":"Watching videos is a creative activity, while making them is easy.","misconceptionCategory":"meaning_confusion"},{"text":"Watching videos is an active activity, while making them is creative.","misconceptionCategory":"polarity_change"},{"text":"Making videos involves no active part, while watching them is creative.","misconceptionCategory":"role_reversal"}],"linkedVocabularyIds":["vocab_passive_9"],"primaryEvidenceTargetId":"vocab_passive_9"}'::jsonb,'live'),
('u9_idea_interactive',9,'idea_set','{"originalIdea":"The new website is interactive, so visitors can ask questions and get answers immediately.","accurateParaphrases":["Visitors to the new website can take part by asking questions and receiving instant answers.","The new website responds to its users, who can ask questions and get answers at once.","Because the new website reacts to users, people can ask questions and receive replies straight away."],"meaningInvariants":[{"type":"meaning","value":"responds to users"}],"distractors":[{"text":"The new website is popular, so visitors can ask questions and get answers immediately.","misconceptionCategory":"meaning_confusion"},{"text":"The new website is one-way, so visitors cannot ask questions or get answers.","misconceptionCategory":"polarity_change"},{"text":"The new website will soon respond to users, so visitors will be able to ask questions.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_interactive_9"],"primaryEvidenceTargetId":"vocab_interactive_9"}'::jsonb,'live'),
('u9_idea_tech_savvy',9,'idea_set','{"originalIdea":"My grandfather is surprisingly tech-savvy and edits his own videos.","accurateParaphrases":["My grandfather is unexpectedly good with technology and edits his own videos.","Surprisingly, my grandfather knows a lot about modern technology and edits his own videos.","My grandfather understands technology well, which is surprising, and he edits his own videos."],"meaningInvariants":[{"type":"meaning","value":"good with technology"}],"distractors":[{"text":"My grandfather is surprisingly afraid of technology but edits his own videos.","misconceptionCategory":"polarity_change"},{"text":"My grandfather is surprisingly famous and edits his own videos.","misconceptionCategory":"meaning_confusion"},{"text":"My grandfather is a little good with technology and sometimes watches videos.","misconceptionCategory":"degree_change"}],"linkedVocabularyIds":["vocab_tech_savvy"],"primaryEvidenceTargetId":"vocab_tech_savvy"}'::jsonb,'live'),
('u9_idea_digital_native',9,'idea_set','{"originalIdea":"As a digital native, Mia learned to use a tablet before she could read.","accurateParaphrases":["Mia grew up with technology, so she could use a tablet before she was able to read.","Having been surrounded by digital devices from birth, Mia used a tablet before she learned to read.","Mia has used technology all her life and could work a tablet before reading."],"meaningInvariants":[{"type":"meaning","value":"grew up with digital technology"}],"distractors":[{"text":"As a computer engineer, Mia learned to use a tablet before she could read.","misconceptionCategory":"meaning_confusion"},{"text":"As someone who came to technology late, Mia learned to use a tablet after she could read.","misconceptionCategory":"polarity_change"},{"text":"As someone who grew up with technology, Mia learned to read before she could use a tablet.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_digital_native"],"primaryEvidenceTargetId":"vocab_digital_native"}'::jsonb,'live'),
('u9_idea_accuracy',9,'idea_set','{"originalIdea":"Journalists must check the accuracy of every fact before publishing a story.","accurateParaphrases":["Before a story is published, journalists have to make sure every fact is correct.","Every fact must be checked for correctness by journalists before a story appears.","Journalists need to confirm that each fact is right before they publish a story."],"meaningInvariants":[{"type":"meaning","value":"correctness"}],"distractors":[{"text":"Journalists must check the popularity of every fact before publishing a story.","misconceptionCategory":"meaning_confusion"},{"text":"Journalists must check the correctness of some facts after publishing a story.","misconceptionCategory":"time_change"},{"text":"Readers must check the correctness of every fact before journalists publish a story.","misconceptionCategory":"role_reversal"}],"linkedVocabularyIds":["vocab_accuracy"],"primaryEvidenceTargetId":"vocab_accuracy"}'::jsonb,'live'),
('u9_idea_appropriate',9,'idea_set','{"originalIdea":"Shorts and flip-flops are not appropriate for a job interview.","accurateParaphrases":["Shorts and flip-flops are not suitable clothes for a job interview.","You should not wear shorts and flip-flops to a job interview because they are not right for it.","A job interview is the wrong situation for shorts and flip-flops."],"meaningInvariants":[{"type":"meaning","value":"suitable"}],"distractors":[{"text":"Shorts and flip-flops are not comfortable for a job interview.","misconceptionCategory":"meaning_confusion"},{"text":"Shorts and flip-flops are perfectly suitable for a job interview.","misconceptionCategory":"polarity_change"},{"text":"Shorts and flip-flops are not suitable for a day at the beach.","misconceptionCategory":"scope_change"}],"linkedVocabularyIds":["vocab_appropriate"],"primaryEvidenceTargetId":"vocab_appropriate"}'::jsonb,'live'),
('u9_idea_banned',9,'idea_set','{"originalIdea":"Mobile phones are banned during exams at our school.","accurateParaphrases":["At our school, mobile phones are not allowed during exams.","Our school does not permit students to use mobile phones in exams.","During exams at our school, phones are forbidden."],"meaningInvariants":[{"type":"meaning","value":"not allowed"}],"distractors":[{"text":"Mobile phones are required during exams at our school.","misconceptionCategory":"polarity_change"},{"text":"Mobile phones are sold during exams at our school.","misconceptionCategory":"meaning_confusion"},{"text":"Mobile phones will be forbidden during exams at our school next year.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_banned"],"primaryEvidenceTargetId":"vocab_banned"}'::jsonb,'live'),
('u9_idea_community',9,'idea_set','{"originalIdea":"The whole community helped to rebuild the library after the flood.","accurateParaphrases":["Everyone in the area helped to rebuild the library after the flood.","After the flood, all the local people worked together to rebuild the library.","The people living in the area all joined in to rebuild the library when the flood was over."],"meaningInvariants":[{"type":"meaning","value":"the people of the area"}],"distractors":[{"text":"The whole council helped to rebuild the library after the flood.","misconceptionCategory":"meaning_confusion"},{"text":"A few local people helped to rebuild the library after the flood.","misconceptionCategory":"quantity_change"},{"text":"All the local people damaged the library during the flood.","misconceptionCategory":"action_change"}],"linkedVocabularyIds":["vocab_community"],"primaryEvidenceTargetId":"vocab_community"}'::jsonb,'live'),
('u9_idea_optional',9,'idea_set','{"originalIdea":"The extra Saturday class is optional, so nobody has to attend.","accurateParaphrases":["Students can choose whether to go to the extra Saturday class; it is not required.","Nobody is forced to attend the extra Saturday class because it is a matter of choice.","Going to the extra Saturday class is up to each student."],"meaningInvariants":[{"type":"meaning","value":"a matter of choice"}],"distractors":[{"text":"The extra Saturday class is compulsory, so everybody has to attend.","misconceptionCategory":"polarity_change"},{"text":"The extra Saturday class is cancelled, so nobody can attend.","misconceptionCategory":"meaning_confusion"},{"text":"The extra Saturday class was a matter of choice last year.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_optional"],"primaryEvidenceTargetId":"vocab_optional"}'::jsonb,'live'),
('u9_idea_survive',9,'idea_set','{"originalIdea":"Some experts think that printed newspapers will not survive for another twenty years.","accurateParaphrases":["Some experts believe printed newspapers will have disappeared within twenty years.","According to some experts, printed newspapers will stop existing in the next twenty years.","Some experts expect that printed newspapers will not continue to exist for twenty more years."],"meaningInvariants":[{"type":"meaning","value":"continue to exist"}],"distractors":[{"text":"Some experts think that printed newspapers will become more popular in the next twenty years.","misconceptionCategory":"meaning_confusion"},{"text":"All experts are sure that printed newspapers will disappear in twenty years.","misconceptionCategory":"certainty_change"},{"text":"Some experts think that printed newspapers will continue to exist for another twenty years.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_survive"],"primaryEvidenceTargetId":"vocab_survive"}'::jsonb,'live'),
('u9_idea_unlike',9,'idea_set','{"originalIdea":"Unlike her sister, Amy prefers to phone people rather than send messages.","accurateParaphrases":["Amy, who is different from her sister, would rather phone people than message them.","Amy likes phone calls more than messages, but her sister does not.","In contrast to her sister, Amy chooses calling over sending messages."],"meaningInvariants":[{"type":"contrast","value":"different from her sister"}],"distractors":[{"text":"Like her sister, Amy prefers to phone people rather than send messages.","misconceptionCategory":"polarity_change"},{"text":"Unlike Amy, her sister prefers to phone people rather than send messages.","misconceptionCategory":"role_reversal"},{"text":"Because of her sister, Amy prefers to phone people rather than send messages.","misconceptionCategory":"cause_change"}],"linkedVocabularyIds":["vocab_unlike"],"primaryEvidenceTargetId":"vocab_unlike"}'::jsonb,'live'),
('u9_idea_frustration',9,'idea_set','{"originalIdea":"He felt great frustration when the website crashed for the third time.","accurateParaphrases":["He felt very annoyed when the website stopped working for the third time.","When the website broke down again for the third time, he was extremely irritated.","The third crash of the website made him feel really annoyed and helpless."],"meaningInvariants":[{"type":"meaning","value":"annoyed because unable to do something"}],"distractors":[{"text":"He felt great relief when the website crashed for the third time.","misconceptionCategory":"polarity_change"},{"text":"He felt slight annoyance when the website crashed for the third time.","misconceptionCategory":"degree_change"},{"text":"He felt great fear when the website crashed for the third time.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_frustration"],"primaryEvidenceTargetId":"vocab_frustration"}'::jsonb,'live'),
('u9_idea_informal',9,'idea_set','{"originalIdea":"You can use an informal style in a message to a close friend.","accurateParaphrases":["A relaxed, chatty style is fine when you write to a close friend.","When messaging a good friend, you do not need to write formally.","Writing to a close friend allows a casual, friendly way of writing."],"meaningInvariants":[{"type":"meaning","value":"relaxed and friendly"}],"distractors":[{"text":"You must use a formal style in a message to a close friend.","misconceptionCategory":"polarity_change"},{"text":"You can use a relaxed style in a letter to a head teacher.","misconceptionCategory":"scope_change"},{"text":"You can use a funny style in a message to a close friend.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_informal"],"primaryEvidenceTargetId":"vocab_informal"}'::jsonb,'live'),
('u9_idea_casual',9,'idea_set','{"originalIdea":"Most people wear casual clothes to the office on Fridays.","accurateParaphrases":["On Fridays, most people go to the office in relaxed, everyday clothes.","Most office workers dress comfortably rather than smartly on Fridays.","Fridays are a day when most people wear informal clothes to work."],"meaningInvariants":[{"type":"meaning","value":"relaxed and everyday"}],"distractors":[{"text":"Most people wear smart clothes to the office on Fridays.","misconceptionCategory":"polarity_change"},{"text":"A few people wear relaxed clothes to the office on Fridays.","misconceptionCategory":"quantity_change"},{"text":"Most people wear expensive clothes to the office on Fridays.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_casual"],"primaryEvidenceTargetId":"vocab_casual"}'::jsonb,'live'),
('u9_idea_workforce',9,'idea_set','{"originalIdea":"Over half of the company’s workforce now works from home.","accurateParaphrases":["More than half of the people employed by the company now work from home.","Most of the company’s staff now do their jobs at home.","Over fifty per cent of the company’s employees currently work from home."],"meaningInvariants":[{"type":"quantity","value":"more than half of the workers"}],"distractors":[{"text":"Over half of the company’s customers now shop from home.","misconceptionCategory":"meaning_confusion"},{"text":"A small number of the company’s employees now work from home.","misconceptionCategory":"quantity_change"},{"text":"Over half of the company’s employees used to work from home.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_workforce"],"primaryEvidenceTargetId":"vocab_workforce"}'::jsonb,'live'),
('u9_idea_generation',9,'idea_set','{"originalIdea":"The older generation often prefers phone calls to text messages.","accurateParaphrases":["Older people as a group often like phone calls more than text messages.","People of an older age group tend to choose calls rather than messages.","Many older people would rather talk on the phone than send a text."],"meaningInvariants":[{"type":"meaning","value":"people of a similar age"}],"distractors":[{"text":"The younger generation often prefers phone calls to text messages.","misconceptionCategory":"role_change"},{"text":"The older generation always prefers phone calls to text messages.","misconceptionCategory":"degree_change"},{"text":"The older generation often prefers text messages to phone calls.","misconceptionCategory":"comparison_reversal"}],"linkedVocabularyIds":["vocab_generation_9"],"primaryEvidenceTargetId":"vocab_generation_9"}'::jsonb,'live'),
('u9_idea_perception',9,'idea_set','{"originalIdea":"The advert changed the public perception of electric cars.","accurateParaphrases":["The advert changed the way people think about electric cars.","After the advert, people saw electric cars differently.","Public opinion about electric cars was changed by the advert."],"meaningInvariants":[{"type":"meaning","value":"the way people see something"}],"distractors":[{"text":"The advert changed the price of electric cars.","misconceptionCategory":"meaning_confusion"},{"text":"The advert did not change the way people think about electric cars.","misconceptionCategory":"polarity_change"},{"text":"The advert will change the way people think about electric cars.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_perception"],"primaryEvidenceTargetId":"vocab_perception"}'::jsonb,'live'),
('u9_idea_non_verbal',9,'idea_set','{"originalIdea":"Non-verbal signals, such as smiling, can show how someone really feels.","accurateParaphrases":["Signs without words, such as smiling, can reveal a person’s true feelings.","Smiling and other wordless signals can show someone’s real feelings.","Body language like a smile can show how a person truly feels."],"meaningInvariants":[{"type":"meaning","value":"without words"}],"distractors":[{"text":"Spoken signals, such as shouting, can show how someone really feels.","misconceptionCategory":"meaning_confusion"},{"text":"Signals without words, such as smiling, can hide how someone really feels.","misconceptionCategory":"polarity_change"},{"text":"Signals without words, such as smiling, always show how someone really feels.","misconceptionCategory":"certainty_change"}],"linkedVocabularyIds":["vocab_non_verbal"],"primaryEvidenceTargetId":"vocab_non_verbal"}'::jsonb,'live'),
('u9_idea_underlying',9,'idea_set','{"originalIdea":"The underlying reason for the argument was jealousy, not money.","accurateParaphrases":["The real, hidden cause of the argument was jealousy rather than money.","Although money seemed to be the cause, the true reason for the argument was jealousy.","Jealousy, not money, was the deeper reason behind the argument."],"meaningInvariants":[{"type":"meaning","value":"real but hidden"}],"distractors":[{"text":"The obvious reason for the argument was jealousy, not money.","misconceptionCategory":"meaning_confusion"},{"text":"The real reason for the argument was money, not jealousy.","misconceptionCategory":"role_reversal"},{"text":"One small reason for the argument was jealousy, not money.","misconceptionCategory":"degree_change"}],"linkedVocabularyIds":["vocab_underlying"],"primaryEvidenceTargetId":"vocab_underlying"}'::jsonb,'live'),
('u9_idea_differentiate',9,'idea_set','{"originalIdea":"Young children often cannot differentiate between adverts and real videos.","accurateParaphrases":["Young children are often unable to tell adverts and real videos apart.","Many young children cannot see the difference between adverts and genuine videos.","It is often hard for young children to recognise which videos are adverts and which are real."],"meaningInvariants":[{"type":"meaning","value":"tell apart"}],"distractors":[{"text":"Young children often cannot choose between adverts and real videos.","misconceptionCategory":"meaning_confusion"},{"text":"Young children can easily tell adverts and real videos apart.","misconceptionCategory":"polarity_change"},{"text":"Older adults often cannot tell adverts and real videos apart.","misconceptionCategory":"role_change"}],"linkedVocabularyIds":["vocab_differentiate"],"primaryEvidenceTargetId":"vocab_differentiate"}'::jsonb,'live'),
('u9_idea_physical',9,'idea_set','{"originalIdea":"The bookshop closed its physical store and now sells only online.","accurateParaphrases":["The bookshop shut its real shop and now does business only on the internet.","Now that its real store has closed, the bookshop sells only through its website.","The bookshop no longer has a shop you can visit and sells only online."],"meaningInvariants":[{"type":"meaning","value":"real, not online"}],"distractors":[{"text":"The bookshop closed its online store and now sells only in its real shop.","misconceptionCategory":"role_reversal"},{"text":"The bookshop closed its largest store and now sells only online.","misconceptionCategory":"meaning_confusion"},{"text":"The bookshop will close its real store and sell only online.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_physical"],"primaryEvidenceTargetId":"vocab_physical"}'::jsonb,'live'),
('u9_idea_platform',9,'idea_set','{"originalIdea":"The teacher uses an online platform to share homework with the class.","accurateParaphrases":["The teacher shares homework with the class through an online system.","Homework is given to the class through a website that the teacher uses.","The class receives homework from the teacher via an internet service."],"meaningInvariants":[{"type":"meaning","value":"online system"}],"distractors":[{"text":"The teacher uses a printed book to share homework with the class.","misconceptionCategory":"meaning_confusion"},{"text":"The students use an online system to share homework with the teacher.","misconceptionCategory":"role_reversal"},{"text":"The teacher used to use an online system to share homework with the class.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_platform"],"primaryEvidenceTargetId":"vocab_platform"}'::jsonb,'live'),
('u9_idea_virtual',9,'idea_set','{"originalIdea":"Students who could not travel joined the virtual tour of the museum.","accurateParaphrases":["Students who were unable to travel took part in the online tour of the museum.","The museum tour was also available online for students who could not go there.","Those who could not travel visited the museum on the internet instead."],"meaningInvariants":[{"type":"meaning","value":"online, not in person"}],"distractors":[{"text":"Students who could not travel joined the guided tour of the museum in person.","misconceptionCategory":"polarity_change"},{"text":"Students who could travel joined the online tour of the museum.","misconceptionCategory":"role_change"},{"text":"Students who could not travel joined the free tour of the museum.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_virtual"],"primaryEvidenceTargetId":"vocab_virtual"}'::jsonb,'live'),
('u9_idea_face_to_face',9,'idea_set','{"originalIdea":"Some problems are better discussed face-to-face than by text message.","accurateParaphrases":["Some problems are easier to talk about in person than by message.","It is better to meet and talk about certain problems than to send texts.","For some problems, meeting the other person works better than messaging."],"meaningInvariants":[{"type":"comparison","value":"in person is better"}],"distractors":[{"text":"Some problems are better discussed by text message than in person.","misconceptionCategory":"comparison_reversal"},{"text":"All problems are better discussed in person than by text message.","misconceptionCategory":"quantity_change"},{"text":"Some problems are better discussed by phone than by text message.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_face_to_face"],"primaryEvidenceTargetId":"vocab_face_to_face"}'::jsonb,'live'),
('u9_idea_conference',9,'idea_set','{"originalIdea":"Over two thousand teachers attended the conference on online learning.","accurateParaphrases":["More than two thousand teachers went to the large formal meeting about online learning.","A big meeting about online learning was attended by over two thousand teachers.","Over two thousand teachers took part in the event where experts discussed online learning."],"meaningInvariants":[{"type":"meaning","value":"large formal meeting"}],"distractors":[{"text":"Over two thousand teachers took the course on online learning.","misconceptionCategory":"meaning_confusion"},{"text":"About two hundred teachers attended the large meeting on online learning.","misconceptionCategory":"quantity_change"},{"text":"Over two thousand teachers will attend the large meeting on online learning.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_conference"],"primaryEvidenceTargetId":"vocab_conference"}'::jsonb,'live'),
('u9_idea_suitable',9,'idea_set','{"originalIdea":"This hall is not suitable for a concert with five hundred people.","accurateParaphrases":["This hall is not right for a concert with five hundred people.","A concert for five hundred people could not be held properly in this hall.","The hall does not meet the needs of a concert for five hundred people."],"meaningInvariants":[{"type":"meaning","value":"right for the purpose"}],"distractors":[{"text":"This hall is perfect for a concert with five hundred people.","misconceptionCategory":"polarity_change"},{"text":"This hall is not available for a concert with five hundred people.","misconceptionCategory":"meaning_confusion"},{"text":"This hall is not right for a concert with fifty people.","misconceptionCategory":"quantity_change"}],"linkedVocabularyIds":["vocab_suitable"],"primaryEvidenceTargetId":"vocab_suitable"}'::jsonb,'live'),
('u9_idea_underlying_meaning',9,'idea_set','{"originalIdea":"The underlying meaning of the story is that friendship matters more than money.","accurateParaphrases":["The deeper message of the story is that friends are more important than money.","Beneath the surface, the story tells us that friendship is worth more than money.","What the story is really saying is that money is less important than friendship."],"meaningInvariants":[{"type":"meaning","value":"deeper message"}],"distractors":[{"text":"The title of the story is that friendship matters more than money.","misconceptionCategory":"meaning_confusion"},{"text":"The deeper message of the story is that money matters more than friendship.","misconceptionCategory":"comparison_reversal"},{"text":"The deeper message of the story is that friendship and money do not matter.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_underlying_meaning"],"primaryEvidenceTargetId":"vocab_underlying_meaning"}'::jsonb,'live'),
('u9_idea_informal_language',9,'idea_set','{"originalIdea":"Examiners expect students to avoid informal language in a formal report.","accurateParaphrases":["Examiners want students not to use chatty, everyday words in a formal report.","In a formal report, students should not use slang or casual expressions.","A formal report should not contain the relaxed words people use with friends."],"meaningInvariants":[{"type":"meaning","value":"chatty, everyday words"}],"distractors":[{"text":"Examiners expect students to use chatty, everyday words in a formal report.","misconceptionCategory":"polarity_change"},{"text":"Examiners expect students to avoid technical words in a formal report.","misconceptionCategory":"meaning_confusion"},{"text":"Examiners expect students to avoid chatty words in a message to a friend.","misconceptionCategory":"scope_change"}],"linkedVocabularyIds":["vocab_informal_language"],"primaryEvidenceTargetId":"vocab_informal_language"}'::jsonb,'live'),
('u9_idea_formal_style',9,'idea_set','{"originalIdea":"A job application should be written in a formal style.","accurateParaphrases":["A job application should be written in a serious, polite way.","When you apply for a job, you should write politely and without slang.","Writing for a job application should be official and careful in tone."],"meaningInvariants":[{"type":"meaning","value":"serious and polite"}],"distractors":[{"text":"A job application should be written in a chatty style.","misconceptionCategory":"polarity_change"},{"text":"A job application should be written in a short style.","misconceptionCategory":"meaning_confusion"},{"text":"A job application can sometimes be written in a serious style.","misconceptionCategory":"modality_change"}],"linkedVocabularyIds":["vocab_formal_style"],"primaryEvidenceTargetId":"vocab_formal_style"}'::jsonb,'live'),
('u9_idea_reporting_verb',9,'idea_set','{"originalIdea":"Using a precise reporting verb such as “admitted” makes your summary clearer.","accurateParaphrases":["Choosing an exact word like “admitted” to tell the reader what someone said makes your summary clearer.","Your summary becomes clearer if you introduce what people said with exact verbs such as “admitted”.","A summary is clearer when you use specific verbs like “admitted” instead of always using “said”."],"meaningInvariants":[{"type":"meaning","value":"verb that tells us what someone said"}],"distractors":[{"text":"Using a precise adjective such as “admitted” makes your summary clearer.","misconceptionCategory":"meaning_confusion"},{"text":"Using a vague verb such as “said” makes your summary clearer.","misconceptionCategory":"polarity_change"},{"text":"Using an exact verb such as “admitted” makes your summary longer.","misconceptionCategory":"detail_change"}],"linkedVocabularyIds":["vocab_reporting_verb"],"primaryEvidenceTargetId":"vocab_reporting_verb"}'::jsonb,'live'),
('u9_idea_direct_object',9,'idea_set','{"originalIdea":"In “Leo sent a message”, “a message” is the direct object.","accurateParaphrases":["In “Leo sent a message”, “a message” is the thing that receives the action of the verb.","In “Leo sent a message”, the thing Leo sent, “a message”, is what the verb acts on.","The words “a message” in “Leo sent a message” tell us what was sent."],"meaningInvariants":[{"type":"meaning","value":"receives the action of the verb"}],"distractors":[{"text":"In “Leo sent a message”, “a message” is the subject.","misconceptionCategory":"meaning_confusion"},{"text":"In “Leo sent a message”, “Leo” receives the action of the verb.","misconceptionCategory":"role_reversal"},{"text":"In “Leo sent a message”, “sent” is the word that receives the action.","misconceptionCategory":"detail_change"}],"linkedVocabularyIds":["vocab_direct_object"],"primaryEvidenceTargetId":"vocab_direct_object"}'::jsonb,'live'),
('u9_idea_clause',9,'idea_set','{"originalIdea":"A sentence such as “I stayed home because it rained” contains two clauses.","accurateParaphrases":["The sentence “I stayed home because it rained” has two groups of words, each with its own subject and verb.","In “I stayed home because it rained”, there are two parts, and each has a subject and a verb.","“I stayed home” and “because it rained” each contain a subject and a verb."],"meaningInvariants":[{"type":"quantity","value":"two subject-verb groups"}],"distractors":[{"text":"A sentence such as “I stayed home because it rained” contains two paragraphs.","misconceptionCategory":"meaning_confusion"},{"text":"A sentence such as “I stayed home because it rained” contains one subject-verb group.","misconceptionCategory":"quantity_change"},{"text":"A sentence such as “I stayed home because it rained” contains no verbs.","misconceptionCategory":"omitted_information"}],"linkedVocabularyIds":["vocab_clause"],"primaryEvidenceTargetId":"vocab_clause"}'::jsonb,'live'),
('u9_idea_suggest',9,'idea_set','{"originalIdea":"My teacher suggested that I read an English article every day.","accurateParaphrases":["My teacher put forward the idea that I should read an English article daily.","My teacher advised me, as an idea to consider, to read one English article each day.","My teacher proposed that I read an article in English every day."],"meaningInvariants":[{"type":"meaning","value":"put forward an idea"}],"distractors":[{"text":"My teacher ordered me to read an English article every day.","misconceptionCategory":"degree_change"},{"text":"I proposed that my teacher read an English article every day.","misconceptionCategory":"role_reversal"},{"text":"My teacher refused to let me read an English article every day.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_suggest"],"primaryEvidenceTargetId":"vocab_suggest"}'::jsonb,'live'),
('u9_idea_recommend',9,'idea_set','{"originalIdea":"Most reviewers recommend the app to people who are learning languages.","accurateParaphrases":["Most reviewers say the app is good and advise language learners to use it.","The majority of reviewers think language learners should try the app.","Most reviewers advise people studying languages to use the app."],"meaningInvariants":[{"type":"meaning","value":"say something is good and advise using it"}],"distractors":[{"text":"Most reviewers warn language learners not to use the app.","misconceptionCategory":"polarity_change"},{"text":"A few reviewers advise language learners to use the app.","misconceptionCategory":"quantity_change"},{"text":"Most reviewers designed the app for people who are learning languages.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_recommend_9"],"primaryEvidenceTargetId":"vocab_recommend_9"}'::jsonb,'live'),
('u9_idea_solution',9,'idea_set','{"originalIdea":"Creating a silent study room was a simple solution to the noise problem.","accurateParaphrases":["A silent study room was an easy way to deal with the noise problem.","The noise problem was solved easily by creating a silent study room.","Making a quiet room for studying simply fixed the problem of noise."],"meaningInvariants":[{"type":"meaning","value":"way of dealing with a problem"}],"distractors":[{"text":"Creating a silent study room was a simple cause of the noise problem.","misconceptionCategory":"meaning_confusion"},{"text":"Creating a silent study room was an expensive and difficult way to deal with the noise problem.","misconceptionCategory":"detail_change"},{"text":"Creating a silent study room made the noise problem worse.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_solution_9"],"primaryEvidenceTargetId":"vocab_solution_9"}'::jsonb,'live'),
('u9_idea_introduction',9,'idea_set','{"originalIdea":"A good introduction tells the reader what the essay will be about.","accurateParaphrases":["A good opening paragraph explains to the reader what the essay will discuss.","The first part of a good essay shows the reader what the topic is.","An effective beginning lets the reader know the subject of the essay."],"meaningInvariants":[{"type":"meaning","value":"opening part"}],"distractors":[{"text":"A good conclusion tells the reader what the essay was about.","misconceptionCategory":"meaning_confusion"},{"text":"A good opening hides from the reader what the essay will be about.","misconceptionCategory":"polarity_change"},{"text":"A good title tells the reader what the essay will be about.","misconceptionCategory":"detail_change"}],"linkedVocabularyIds":["vocab_introduction"],"primaryEvidenceTargetId":"vocab_introduction"}'::jsonb,'live'),
('u9_idea_conclusion',9,'idea_set','{"originalIdea":"The scientists came to the conclusion that the medicine was safe.","accurateParaphrases":["The scientists decided, after studying the evidence, that the medicine was safe.","After considering the results, the scientists judged the medicine to be safe.","The scientists’ final judgement was that the medicine was safe."],"meaningInvariants":[{"type":"meaning","value":"decision after studying evidence"}],"distractors":[{"text":"The scientists came to the conclusion that the medicine was dangerous.","misconceptionCategory":"polarity_change"},{"text":"The scientists hoped that the medicine was safe.","misconceptionCategory":"certainty_change"},{"text":"The scientists will decide whether the medicine is safe.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_conclusion"],"primaryEvidenceTargetId":"vocab_conclusion"}'::jsonb,'live'),
('u9_idea_audience',9,'idea_set','{"originalIdea":"The speaker kept her audience interested by telling stories.","accurateParaphrases":["The speaker held the attention of the people listening by telling stories.","By telling stories, the speaker made sure her listeners stayed interested.","The people listening to the speaker stayed interested because she told stories."],"meaningInvariants":[{"type":"meaning","value":"people listening"}],"distractors":[{"text":"The speaker kept her assistants interested by telling stories.","misconceptionCategory":"meaning_confusion"},{"text":"The speaker bored her listeners by telling stories.","misconceptionCategory":"polarity_change"},{"text":"The listeners kept the speaker interested by telling stories.","misconceptionCategory":"role_reversal"}],"linkedVocabularyIds":["vocab_audience"],"primaryEvidenceTargetId":"vocab_audience"}'::jsonb,'live'),
('u9_idea_purpose',9,'idea_set','{"originalIdea":"The main purpose of the report is to suggest ways to reduce waste.","accurateParaphrases":["The report mainly aims to propose ways of cutting waste.","The chief aim of the report is to put forward ideas for reducing waste.","Above all, the report was written to recommend how waste can be reduced."],"meaningInvariants":[{"type":"meaning","value":"aim"}],"distractors":[{"text":"The main result of the report is that waste has been reduced.","misconceptionCategory":"meaning_confusion"},{"text":"One small aim of the report is to suggest ways to reduce waste.","misconceptionCategory":"degree_change"},{"text":"The main aim of the report is to suggest ways to increase waste.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_purpose"],"primaryEvidenceTargetId":"vocab_purpose"}'::jsonb,'live'),
('u9_idea_evaluate',9,'idea_set','{"originalIdea":"Students should evaluate each website before using it as a source.","accurateParaphrases":["Students should judge how reliable each website is before using it as a source.","Before using a website as a source, students need to assess its quality.","Each website should be checked and judged by students before they use it."],"meaningInvariants":[{"type":"meaning","value":"judge the quality"}],"distractors":[{"text":"Students should copy each website before using it as a source.","misconceptionCategory":"meaning_confusion"},{"text":"Students should judge each website after using it as a source.","misconceptionCategory":"time_change"},{"text":"Students should trust each website without judging it.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_evaluate_9"],"primaryEvidenceTargetId":"vocab_evaluate_9"}'::jsonb,'live'),
('u9_idea_relevant',9,'idea_set','{"originalIdea":"Only include information that is relevant to the question.","accurateParaphrases":["Only include information that is connected with the question.","Leave out anything that does not relate to the question.","Use only details that are directly linked to the question."],"meaningInvariants":[{"type":"meaning","value":"connected with the subject"}],"distractors":[{"text":"Only include information that is interesting to the reader.","misconceptionCategory":"meaning_confusion"},{"text":"Include all information, even if it is not connected with the question.","misconceptionCategory":"polarity_change"},{"text":"Only include information that is connected with the answer key.","misconceptionCategory":"detail_change"}],"linkedVocabularyIds":["vocab_relevant_9"],"primaryEvidenceTargetId":"vocab_relevant_9"}'::jsonb,'live'),
('u9_idea_constructive',9,'idea_set','{"originalIdea":"The teacher gave constructive feedback that helped me improve my essay.","accurateParaphrases":["The teacher gave helpful comments that showed me how to make my essay better.","My essay improved thanks to the teacher’s useful, positive comments.","The teacher’s feedback was helpful and showed me how to improve my essay."],"meaningInvariants":[{"type":"meaning","value":"helpful and aimed at improvement"}],"distractors":[{"text":"The teacher gave unkind feedback that helped me improve my essay.","misconceptionCategory":"polarity_change"},{"text":"The teacher gave brief feedback that did not help me.","misconceptionCategory":"meaning_confusion"},{"text":"I gave the teacher helpful feedback on her essay.","misconceptionCategory":"role_reversal"}],"linkedVocabularyIds":["vocab_constructive"],"primaryEvidenceTargetId":"vocab_constructive"}'::jsonb,'live'),
